SELECT CAST(COUNT(DISTINCT CASE WHEN a.dischtime - a.admittime <= 30 THEN a.stay_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT a.stay_id), 0) AS readmission_rate, AVG(CASE WHEN a.dischtime - a.admittime <= 30 THEN a.los END) AS avg_los_30d, PERCENT_RANK() OVER (ORDER BY COUNT(CASE WHEN a.dischtime - a.admittime > 4 THEN a.stay_id END)) AS percentile_stay_gt_4d FROM admissions a JOIN patients p ON a.subject_id = p.subject_id JOIN transfers t ON a.subject_id = t.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'F' AND p.anchor_year = 81 AND p.anchor_year_group BETWEEN 76 AND 86 AND t.eventtype = 'transfer' AND d.icd_code IN ('410', 'I21') GROUP BY a.subject_id;